                    resposta = infoPergunta.options.ids;
                    novoJson.answers[questionId] = respostasA;
                } else {
                    resposta = Object.fromEntries(
                        Object.keys(infoPergunta.options).map(optionId => [optionId, infoPergunta.options[optionId].answer])
