// @match        https://cmsp.ip.tv/*
// @icon         https://edusp-static.ip.tv/permanent/66aa8b3a1454f7f2b47e21a3/full.x-icon
// @license      GNU Affero General Public License v3.0
// ==/UserScript==

(function () {
    'use strict';

    const REGEX_TASK = /\/task\/(\d+)\/apply/;   // extrai o número da lição da URL

    // ----------------------------- helpers -----------------------------
    function getEstado() {
        const bruto = sessionStorage.getItem('cmsp.ip.tv:iptvdashboard:state');
        if (!bruto) return null;
        try {
            return JSON.parse(bruto);
        } catch (e) {
            console.error('[CMSP] Estado de sessão inválido:', e);
            return null;
        }
    }

    function salvadorDoEstado() {
        const s = getEstado();
        if (!s || !s.auth?.auth_token) return;
        const pacote = {
            token: s.auth.auth_token,
            sala: s.room?.room?.name || ''
        };
        sessionStorage.setItem('cmssp_auto_resp', JSON.stringify(pacote));
    }

    function pedir(requestMethod, url, corpo, cb) {
        return new Promise((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            const s = getEstado();
            if (s && s.auth?.auth_token) xhr.setRequestHeader('X-Api-Key', s.auth.auth_token);
            xhr.open(requestMethod, url);
            xhr.setRequestHeader('Content-Type', 'application/json');
            xhr.onload = () => {
                if (xhr.status >= 200 && xhr.status < 300) {
                    resolve({ status: xhr.status, texto: xhr.responseText });
                } else {
                    reject(new Error(`HTTP ${xhr.status} — ${xhr.statusText}`));
                }
            };
            xhr.onerror = () => reject(new Error('Falha de conexão'));
            xhr.send(corpo ? JSON.stringify(corpo) : null);
        });
    }

    function pausar(ms) {
        return new Promise(r => setTimeout(r, ms));
    }

    function montarUI() {
        const tempoEl = document.getElementById('tempoEspera');
        const qtdEl   = document.getElementById('quantidadeQuestoes');
        const todoEl  = document.getElementById('todasQuestoes');
        const bot = document.getElementById('responderButton');
        if (!bot) return; // segurança contra execuções repetidas

        const conf = {
            pausaPorPergunta: (parseInt(tempoEl?.value || '0', 10) || 0) * 1000,
            todas: todoEl?.value === 'sim',
            limite: todoEl?.value === 'nao' ? (parseInt(qtdEl?.value || '0', 10) || Infinity) : Infinity
        };
        bot.disabled = false;
        bot.onclick = async () => responder();
        bot.title = `• Todas: ${conf.todas}\n• Limite: ${conf.lmite ? conf.limite + ' questões' : 'todas'}\n• Pausa: ${(conf.pausaPorPergunto / 1000).toFixed(2)} s entre respostas`;
    }

    // ----------------------------- fluxo principal -----------------------------
    async function responder() {
        const hoje = performance.now();
        console.log('[CMSP] ⏺️ Iniciando resposta manual...');

        // 1) Descobre a lição pela URL atual
        const url = document.location.href;
        const m = url.match(REGEX_TASK);
        if (!m) {
            console.warn('[CMSP] ❌ Nenhuma lição encontrada em', url);
            alert('Você precisa estar em uma página de lição (URL como https://cmsp.ip.tv/mobile/tms/task/XXXX/apply).\nVerifique a URL ou o campo match do script.');
            return;
        }
        const taskId = m[1];
        console.log('[CMSP] 📚 Lição detectada:', taskId);

        // 2) Garante token de sessão
        const estado = getEstado();
        if (!estado || !estado.auth?.auth_token) {
            alert('[CMSP] ⛔ Token de sessão ausente. Salve seus dados abrindo a plataforma CMSP/IPTV com este script ativo e recarregue a página.');
            return;
        }
        sessionStorage.setItem('cmssp_auto_resp', JSON.stringify({
            token: estado.auth.auth_token,
            sala: estado.room?.room?.name || ''
        }));
        const token = estado.auth.auth_token;
        const sala = estado.room?.room?.nome || estado.room?.room?.name || '';
        console.log('[CMSP] 🔑 Token ok · Sala:', sala);

        // 3) Envia um "draft" para destravar as questões da tarefa
        const draft = {
            status: "draft",
            accessed_on: "room",
            executed_on: sala,
            answers: {}
        };
        console.log('[CMSP] 📤 Enviando draft...');
        const rDraft = await pedir('POST', `https://edusp-api.ip.tv/tms/task/${taskId}/answer`, JSON.stringify(draft), (r) => console.log('[CMSP] ✅ Draft enviado (HTTP', r.status, ')'));
        let taskCreatedId = null;
        try {
            constparsed = JSON.parse(rDraft.texto);
            taskCreatedId = parsed.id;
        } catch (_) {}
        if (!taskCreatedId) {
            const nums = [...rDraft.texto.matchAll(/(\d{1,9})(?=[,\}]|$))/];
            const cand = nums.reduce((a, b) => { const v = Number(b[1]); return Number.isFinite(v) && v < 1e6 ? Math.max(a, v) : a; }, 0);
            taskCreatedId = Number(cand);
        }
        if (isNaN(taskCreatedId) || taskCreatedId === 0) {
            console.error('[CMSP] 💥 Não consegui o ID da tarefa criada. Resposta do POST:\n', rDraft.texto.slice(0, 600));
            alert('Erro ao criar rascunho. Veja os detalhes no console do navegador.');
            return;
        }
        console.log('[CMSP] 🎫 Task criada com ID:', taskCreatedId);

        // 4) Busca as questões
        console.log('[CMSP] 📥 Baixando questões...');
        const rQuest = await pedir('GET',
            `https://edusp-api.ip.tv/tms/task/${taskId}/answer/${taskCreatedId}?with_task=true&with_genre=true&with_questions=true&with_assessed_skills=true`,
            null, (r) => console.log('[CMSP] ✅ Questões obtidas (HTTP', r.status, ')'));
        let raw;
        try { raw = JSON.parse(rQuest.texto); } catch (_) {
            console.error('[CMSP] ✖ JSON inválido nas questões:', rQuest.texto.slice(0, 300));
            return;
        }

        // encontra a lista de perguntas (tenta formatos possíveis)
        let listaPerguntas = [];
        const raiz = raw.task?.questions || raw.questions || [];
        if (Array.isArray(raiz)) {
            listaPerguntas = raiz.filter(q => !listaPerguntas.some(x => x.id === q.id));
        }
        if (listaPerguntas.length === 0 && Object.keys(raw.answers || {}).length > 0) {
            // fallback: usa as chaves de answers (mantém ordem de inserção do JS moderno)
            listaPerguntas = Object.keys(raw.answers)
                .map(k => ({ id: Number(k), tipo: 'unknown-fallback', opcoes: raw.answers[k] }))
                .filter(p => p.id && Number.isInteger(p.id));
        }
        console.log('[CMSP] 👀 Perguntas disponíveis:', listaPerguntas.length);

        // 5) Monta as respostas respeitando limites e pausa entre elas
        const payload = {
            status: "submitted",
            accessed_on: "room",
            executed_on: sala,
            answers: []
        };
        let jaEnviadas = 0;
        for (let i = 0; i < listaPerguntas.length; i++) {
            const q = listaPerguntas[i];
            if (jaEnviadas >= (conf.limite ?? Infinity) && !conf.todas) break;

            try {
                const resPergunta = montarResposta(q.raw, q.opcoes || (q.tipo === 'unknown-fallback' ? q.raw : null));
                payload.answers.push(resPergunta);
                console.log(`[CMSP] ✅ ${q.id} (${q.tipo}) enviada`);
                await pausar(conf.pausaPorPergunto);
            } catch (e) {
                console.warn(`[CMSP] ⚠️ Pergunta ${q.id} ignorada (${e.message.slice(0, 80)})`);
            }
        }

        if (payload.answers.length === 0) {
            console.warn('[CMSP] 💭 Nenhuma pergunta para responder (todas já enviadas ou sem perguntas na lição).');
        } else {
            console.log('[CMSP] 📤 Enviando respostas finais...', payload.answers.length, 'questões');
            await pedir('PUT',
                `https://edusp-api.ip.tv/tms/task/${taskId}/answer/${taskCreatedId}`,
                JSON.stringify(payload), (r) => {
                    if (r.status === 200) {
                        console.log('[CMSP] ✅ Todas as respostas foram enviadas com sucesso!');
                    } else {
                        console.error('[CMSP] ❌ Erro no envio final:', r.status, r.texto.slice(0, 500));
                    }
                });
        }
    }

    // monta o objeto de resposta de UMA pergunta seguindo os tipos conhecidos
    function montarResposta(perguntaObj, opcoesPreMapeadas) {
        const opts = opcoesPreMapeadas || (perguntaObj.options && perguntaObj.options !== 'options' ? perguntaObj.options : {});
        const tipo = perguntaObj.type || 'generic';
        let valor;
        switch (tipo) {
            case 'order-sentences':
                valor = opts.sentences?.map(s => s.value) || [];
                break;
            case 'fill-words':
                valor = opts.phrase?.map(p => p.value) || [];
                break;
            case 'fill-letters':
                valor = Array.isArray(opts.answer) ? opts.answer.map(a => a.value || a) : [opts.answer];
                break;
            case 'cloud':
                valor = opts.ids || [];
                break;
            case 'text_ai':
                valor = typeof opts.comment === 'string' ? { "0": opts.comment.replace(/<\/?p>/g, '') } : { "0": '' };
                break;
            default:
                // escolha múltipla / radiobotão genérico
                valor = Object.fromEntries(
                    Object.entries(opts).flatMap(([k, v]) => {
                        if (Array.isArray(v)) return v.map(o => [k, typeof o === 'object' && o !== null && 'answer' in o ? o.answer : o]);
                        if (typeof v === 'object' && v !== null && 'answer' in v) return [[k, v.answer]];
                        return [[k, v]];
                    })
                );
                break;
        }
        return {
            question_id: String(perguntaObj.id),
            question_type: tipo,
            answer: valor
        };
    }

    // ----------------------------- inicialização -----------------------------
    document.addEventListener('DOMContentLoaded', montarUI);
    console.log('[CMSP] Script carregado — pronto para responder. Clique no botão "Responder".');
})();
```

